// Obtém o texto vindo do nó HTTP Request (trata campo data ou html)
const inputData = $input.first().json;
const html = inputData.data || inputData.html || JSON.stringify(inputData);

// Remove quebras de linha para o regex capturar a tabela sem problemas
const cleanHtml = html.replace(/(\r\n|\n|\r)/gm, "");

// Expressão regular para capturar as linhas <tr>
const rowRegex = /<tr[^>]*>([\s\S]*?)<\/tr>/gi;
const cellRegex = /<td[^>]*>([\s\S]*?)<\/td>/gi;

const results = [];
let matchRow;

while ((matchRow = rowRegex.exec(cleanHtml)) !== null) {
  const rowContent = matchRow[1];
  const cells = [];
  let matchCell;

  while ((matchCell = cellRegex.exec(rowContent)) !== null) {
    // Remove qualquer tag HTML interna e limpa espaços extras
    const value = matchCell[1].replace(/<[^>]*>/g, "").trim();
    cells.push(value);
  }

  // Se a linha contiver pelo menos 4 colunas (Nome, Email, Saldo, Perfil)
  if (cells.length >= 4) {
    results.push({
      json: {
        nome: cells[0],
        email: cells[1],
        saldo: cells[2],
        perfil: cells[3]
      }
    });
  }
}

// Se por algum motivo o regex não encontrar tabelas <td>, retorna a estrutura padrão para não quebrar o fluxo
if (results.length === 0) {
  return [
    {
      json: {
        alerta: "Nenhum cliente foi extraído do HTML",
        htmlRecebido: html.substring(0, 200) // exibe os primeiros 200 caracteres para depurar
      }
    }
  ];
}

return results;

for (const item of $input.all()) {
  // Tenta obter os dados do objeto do cliente vindos do nó anterior
  const data = item.json;

  const nome = data.nome || "Cliente";
  const perfil = data.perfil || data.recomendacao?.perfil || "Conservador";
  const produto = data.produto || data.recomendacao?.produto || "CDB Liquidez Diária";

  // Trata valor mínimo e rentabilidade
  const minimoVal = data.minimo || data.recomendacao?.minimo || 1000;
  const minimoFormatado = Number(minimoVal).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  const rentabilidade = data.rentabilidade || data.recomendacao?.rentabilidade || "12.5%";

  // Trata saldo numérico e texto
  let saldoNum = data.saldo_num || data.saldo;
  if (typeof saldoNum === 'string') {
    saldoNum = parseFloat(saldoNum.replace(/[^\d,-]/g, '').replace(',', '.')) || 12500;
  } else if (!saldoNum) {
    saldoNum = 12500;
  }

  const saldoTexto = data.saldo_texto || saldoNum.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  // Lista com as 3 variações de mensagens conforme o modelo do desafio
  const mensagens = [
    `Olá ${nome}! Pelo seu perfil (${perfil}), uma boa opção é **${produto}** (mínimo ${minimoFormatado}). Com seu saldo atual (${saldoTexto}), você já consegue investir. Rentabilidade: ${rentabilidade}.`,
    `Oi ${nome}! Recomendações para perfil ${perfil}: **${produto}** (mínimo ${minimoFormatado}). Seu saldo (${saldoTexto}) já atende o mínimo. Rentabilidade: ${rentabilidade}.`,
    `${nome}, indo direto ao ponto: para o perfil ${perfil}, **${produto}** (mínimo ${minimoFormatado}). Você tem ${saldoTexto}, então dá pra aplicar. Rentabilidade: ${rentabilidade}.`
  ];

  // Seleciona aleatoriamente ou define a primeira opção como mensagem escolhida
  const mensagemEscolhida = mensagens[0];

  // Estrutura a saída exatamente igual ao resultado esperado da imagem
  item.json.resultados = {
    saldo_texto: saldoTexto,
    saldo_num: saldoNum,
    Recomendacao: {
      perfil: perfil,
      produto: produto,
      minimo: minimoVal,
      rentabilidade: rentabilidade
    },
    motivo: "saldo_ok",
    mensagens: mensagens,
    mensagem_escolhida: mensagemEscolhida
  };
}

return $input.all();

// Obtém a lista de itens vinda do nó anterior
const items = $input.all();

function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

return items.map(item => {
  const c = item.json;

  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);
  const emailTo = c.email_to || c.email || "cliente@email.com";
  const mensagem = c.mensagem_base || c.mensagem_escolhida || `Olá ${c.nome || 'Cliente'}, temos uma oportunidade para o seu perfil.`;

  return {
    json: {
      email_to: emailTo,
      nome: c.nome || "Cliente",
      perfil: c.perfil || "Conservador",
      saldo_texto: c.saldo_texto || "R$ 0,00",
      saldo_num: saldoNum,
      recomendacao: c.recomendacao || {
        perfil: c.perfil || "Conservador",
        produto: "CDB Liquidez Diária",
        minimo: 1000,
        rentabilidade: "12.5%"
      },
      motivo: c.motivo || "saldo_ok",
      mensagem_base: mensagem,
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: [
          "promessas de ganho",
          "garantias",
          "linguagem agressiva"
        ]
      }
    }
  };
});

