return $input.all().map(item => {
  // Pega o texto puro retornado pelo Gemini
  let rawText = item.json.content?.parts?.[0]?.text || "";

  // Limpa possíveis marcações de código markdown como ```json ... ```
  rawText = rawText.replace(/```json/g, "").replace(/```/g, "").trim();

  let emailDados = {};
  try {
    emailDados = JSON.parse(rawText);
  } catch (e) {
    emailDados = {
      subject: "Oportunidade de Investimento",
      text_body: rawText,
      html_body: `<p>${rawText}</p>`
    };
  }

  return {
    json: {
      ...item.json,
      email_final: emailDados
    }
  };
});
